      out.write("    </div>\n");
      out.write("    <div class=\"bottom-content\" id=\"resultPanel\">\n");
      out.write("        <div class=\"editorial-box\" style=\"color: #888;\">Run a test case or click Submit to view judge execution results.</div>\n");
      out.write("    </div>\n");
      out.write("</section>\n");
      out.write("</section>\n");
      out.write("</main>\n");
      out.write("\n");
      out.write("<script>\n");
      out.write("const visibleCases = ");
      out.print(new com.google.gson.Gson().toJson(visibleCases));
      out.write(";\n");
      out.write("const templates = {\n");
