      out.write(",\n");
      out.write("    \"C++\": ");
      out.print(new com.google.gson.Gson().toJson(cppTemplate));
      out.write(",\n");
      out.write("    \"Java\": ");
      out.print(new com.google.gson.Gson().toJson(javaTemplate));
      out.write(",\n");
      out.write("    \"JavaScript\": ");
      out.print(new com.google.gson.Gson().toJson(jsTemplate));
      out.write("\n");
      out.write("};\n");
      out.write("const problemId = ");
      out.print(problemId);
      out.write(";\n");
      out.write("const editor = document.getElementById('sourceCode');\n");
      out.write("const selector = document.getElementById('languageSelector');\n");
      out.write("\n");
      out.write("let customCases = [], activeCase = 0, busy = false;\n");
      out.write("\n");
      out.write("function allCases() { return visibleCases.concat(customCases); }\n");
      out.write("function cacheKey(lang) { return 'codearena:' + problemId + ':' + lang; }\n");
      out.write("\n");
      out.write("function loadCode() {\n");
      out.write("    const saved = localStorage.getItem(cacheKey(selector.value));\n");
      out.write("    editor.value = (saved === null || !saved.trim()) ? templates[selector.value] : saved;\n");
      out.write("    updateGutter();\n");
      out.write("}\n");
      out.write("\n");
      out.write("function updateGutter() {\n");
      out.write("    const lines = editor.value.split('\\n').length;\n");
      out.write("    document.getElementById('gutter').textContent = Array.from({length: lines}, (_, i) => i + 1).join('\\n');\n");
      out.write("}\n");
      out.write("\n");
      out.write("editor.addEventListener('input', () => {\n");
      out.write("    localStorage.setItem(cacheKey(selector.value), editor.value);\n");
      out.write("    updateGutter();\n");
      out.write("});\n");
      out.write("editor.addEventListener('scroll', () => {\n");
      out.write("    document.getElementById('gutter').scrollTop = editor.scrollTop;\n");
      out.write("});\n");
      out.write("selector.addEventListener('change', loadCode);\n");
      out.write("\n");
      out.write("function drawCases() {\n");
      out.write("    const tabs = document.getElementById('caseTabs');\n");
      out.write("    tabs.innerHTML = '';\n");
      out.write("    allCases().forEach((c, i) => {\n");
      out.write("        const b = document.createElement('button');\n");
      out.write("        b.className = 'case-tab' + (i === activeCase ? ' active' : '');\n");
      out.write("        b.textContent = c.custom ? c.label : 'Case ' + (i + 1);\n");
      out.write("        b.onclick = () => selectCase(i);\n");
      out.write("        tabs.appendChild(b);\n");
      out.write("    });\n");
      out.write("    const add = document.createElement('button');\n");
      out.write("    add.className = 'case-add';\n");
      out.write("    add.title = 'Add custom test case';\n");
      out.write("    add.textContent = '+';\n");
      out.write("    add.onclick = addCustomCase;\n");
      out.write("    tabs.appendChild(add);\n");
      out.write("    selectCase(Math.min(activeCase, Math.max(0, allCases().length - 1)), false);\n");
      out.write("}\n");
      out.write("\n");
      out.write("function selectCase(i, redraw = true) {\n");
      out.write("    activeCase = i;\n");
      out.write("    const c = allCases()[i];\n");
      out.write("    if (!c) return;\n");
      out.write("    if (redraw) {\n");
      out.write("        document.querySelectorAll('.case-tab').forEach((b, n) => b.classList.toggle('active', n === i));\n");
      out.write("    }\n");
      out.write("    document.getElementById('caseInput').value = c.input || '';\n");
      out.write("    const expected = document.getElementById('caseExpected');\n");
      out.write("    expected.value = c.output || '';\n");
      out.write("    expected.readOnly = !c.custom;\n");
      out.write("    expected.placeholder = c.custom ? 'Enter expected output' : '—';\n");
      out.write("    expected.oninput = () => { if (c.custom) c.output = expected.value; };\n");
      out.write("}\n");
      out.write("\n");
      out.write("function addCustomCase() {\n");
      out.write("    customCases.push({ custom: true, label: 'Custom ' + (customCases.length + 1), input: '', output: '' });\n");
      out.write("    activeCase = allCases().length - 1;\n");
      out.write("    drawCases();\n");
      out.write("    document.getElementById('caseInput').focus();\n");
      out.write("}\n");
      out.write("\n");
      out.write("document.getElementById('caseInput').addEventListener('input', e => {\n");
      out.write("    const c = allCases()[activeCase];\n");
      out.write("    if (c) c.input = e.target.value;\n");
      out.write("});\n");
      out.write("\n");
      out.write("function setBottom(name) {\n");
      out.write("    document.querySelectorAll('.bottom-tab').forEach(b => b.classList.toggle('active', b.dataset.bottom === name));\n");
      out.write("    document.querySelectorAll('.bottom-content').forEach(p => p.classList.toggle('active', p.id === (name === 'testcase' ? 'testcasePanel' : 'resultPanel')));\n");
      out.write("}\n");
      out.write("document.querySelectorAll('.bottom-tab').forEach(b => b.addEventListener('click', () => setBottom(b.dataset.bottom)));\n");
      out.write("\n");
      out.write("document.querySelectorAll('.tab-button').forEach(b => b.addEventListener('click', () => {\n");
      out.write("    document.querySelectorAll('.tab-button').forEach(x => x.classList.toggle('active', x === b));\n");
      out.write("    document.querySelectorAll('.pane-content').forEach(p => p.classList.toggle('active', p.id === b.dataset.panel));\n");
      out.write("}));\n");
      out.write("\n");
      out.write("function escapeHtml(s) {\n");
      out.write("    return String(s == null ? '' : s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n");
      out.write("}\n");
      out.write("\n");
      out.write("async function runCode(action) {\n");
      out.write("    if (busy) return;\n");
      out.write("    const c = allCases()[activeCase];\n");
      out.write("    if (!c) {\n");
      out.write("        showResult({ status: 'NO_TEST_CASES', message: 'Add a custom test case or select a valid problem.' });\n");
      out.write("        return;\n");
      out.write("    }\n");
      out.write("    busy = true;\n");
      out.write("    const btn = document.getElementById('submitButton');\n");
      out.write("    btn.disabled = true;\n");
      out.write("    document.getElementById('resultPill').textContent = 'Evaluating…';\n");
      out.write("    setBottom('result');\n");
      out.write("    showResult({ status: 'RUNNING', message: 'Running program against judge test cases…' });\n");
      out.write("\n");
      out.write("    const data = new URLSearchParams(new FormData(document.getElementById('codeForm')));\n");
      out.write("    data.set('action', action);\n");
      out.write("    data.set('testCaseIndex', c.custom ? '-1' : String(c.index));\n");
      out.write("    data.set('testInput', document.getElementById('caseInput').value);\n");
      out.write("    if (c.custom) data.set('customExpectedOutput', c.output || '');\n");
      out.write("\n");
      out.write("    try {\n");
      out.write("        const response = await fetch('");
      out.print(ctx);
      out.write("/submitCodeAjax', {\n");
      out.write("            method: 'POST',\n");
      out.write("            headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },\n");
      out.write("            body: data\n");
      out.write("        });\n");
      out.write("        const result = await response.json();\n");
      out.write("        showResult(result);\n");
      out.write("        if (result.status === 'ACCEPTED' && action === 'submit') {\n");
      out.write("            document.getElementById('solvedTag').textContent = 'Solved ✓';\n");
      out.write("        }\n");
      out.write("    } catch (error) {\n");
      out.write("        showResult({ status: 'CONNECTION ERROR', message: 'Could not communicate with the judge backend server.' });\n");
      out.write("    } finally {\n");
      out.write("        busy = false;\n");
      out.write("        btn.disabled = false;\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("function showResult(r) {\n");
      out.write("    const ok = r.status === 'ACCEPTED';\n");
      out.write("    const cls = ok ? 'status-accepted' : 'status-failed';\n");
      out.write("    let html = '<div class=\"result-summary\"><span class=\"result-status ' + cls + '\">' + escapeHtml(r.status || 'ERROR') + '</span><span class=\"result-cases\">' + escapeHtml(r.message || '') + '</span></div>';\n");
      out.write("    \n");
      out.write("    if (r.passedTestCases || r.totalTestCases) {\n");
      out.write("        html += '<div class=\"result-cases\" style=\"margin-bottom:12px; font-weight:600;\">' + Number(r.passedTestCases || 0) + ' / ' + Number(r.totalTestCases || 0) + ' test cases passed &nbsp;·&nbsp; Runtime: ' + Number(r.executionTimeMs || 0) + ' ms &nbsp;·&nbsp; Memory: ' + Number(r.memoryUsedMb || 0) + ' MB</div>';\n");
      out.write("    }\n");
      out.write("    \n");
      out.write("    if (r.hiddenFailure) {\n");
      out.write("        html += '<div class=\"description-callout\">Failed on a hidden judge case. Details are hidden to prevent hardcoding.</div>';\n");
      out.write("    } else if (['COMPILATION_ERROR', 'RUNTIME_ERROR', 'SYSTEM_ERROR', 'TIME_LIMIT_EXCEEDED'].includes(r.status)) {\n");
      out.write("        const diagnostic = r.actualOutput || r.message || 'Execution failed.';\n");
      out.write("        html += '<div class=\"result-block\"><h4>DIAGNOSTICS & ERROR STACK</h4><pre class=\"result-value diff-actual\">' + escapeHtml(diagnostic) + '</pre></div>';\n");
      out.write("    } else if (r.failedTestCase) {\n");
      out.write("        html += '<div class=\"result-block\"><h4>INPUT (CASE ' + Number(r.failedTestCase) + ')</h4><div class=\"result-value\">' + escapeHtml(r.testCaseInput) + '</div></div>' +\n");
      out.write("                '<div class=\"result-block\"><h4>EXPECTED OUTPUT</h4><div class=\"result-value diff-expected\">' + escapeHtml(r.expectedOutput) + '</div></div>' +\n");
      out.write("                '<div class=\"result-block\"><h4>YOUR OUTPUT</h4><pre class=\"result-value diff-actual\">' + escapeHtml(r.actualOutput) + '</pre></div>';\n");
      out.write("    } else if (r.status === 'ACCEPTED' && r.actualOutput) {\n");
      out.write("        html += '<div class=\"result-block\"><h4>OUTPUT</h4><div class=\"result-value diff-expected\">' + escapeHtml(r.actualOutput) + '</div></div>';\n");
      out.write("    }\n");
      out.write("    \n");
      out.write("    document.getElementById('resultPanel').innerHTML = html;\n");
      out.write("    document.getElementById('resultPill').textContent = r.status === 'ACCEPTED' ? '✓ Accepted' : (r.failedTestCase ? 'Case ' + r.failedTestCase + ' Failed' : r.status);\n");
      out.write("}\n");
      out.write("\n");
      out.write("function resetCode() {\n");
      out.write("    if (confirm('Reset editor to starter solution template?')) {\n");
      out.write("        localStorage.removeItem(cacheKey(selector.value));\n");
      out.write("        loadCode();\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("async function copyCode() {\n");
      out.write("    try {\n");
      out.write("        await navigator.clipboard.writeText(editor.value);\n");
      out.write("        document.querySelector('.editor-state').textContent = 'Copied to clipboard';\n");
      out.write("        setTimeout(() => document.querySelector('.editor-state').textContent = '● Autosaved', 2000);\n");
      out.write("    } catch(e) {\n");
      out.write("        document.querySelector('.editor-state').textContent = 'Clipboard write failed';\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("drawCases();\n");
      out.write("loadCode();\n");
      out.write("</script>\n");
      out.write("</body>\n");
